from pathlib import Path
import json
p=Path(__file__).parent
def e(k,t,tag='span',cls=''):return f'<{tag} data-edit="{k}" class="{cls}">{t}</{tag}>'
def foot(n,t):return '<footer>'+e('disclaimer','虚构计划／暂无实测结果')+f'<span>{n}／{t}</span></footer>'
def photo(k,caption):
 a=json.loads((p/'asset-config.json').read_text()).get(k,{}) if (p/'asset-config.json').exists() else {};ident='AI生成概念插画，非现场记录。' if a.get('sourceKind')=='ai-generated' else '图像待接入，未完成视觉验收。'
 return f'<figure class="photo photo-{k}"><div class="image-window" data-asset="{k}"><img src="assets/{k.lower()}.png" alt="图{k}：{ident}"></div><figcaption>'+e('caption-'+k,caption)+f'<strong data-identity="{k}">{ident}</strong></figcaption></figure>'
css=''' :root{--paper:#faf7ed;--ink:#243534;--green:#697850;--red:#b64d35}*{box-sizing:border-box}body{margin:0;background:#dedfd5;color:var(--ink);font-family:"Noto Sans CJK SC","Source Han Sans SC","PingFang SC","Microsoft YaHei",Arial,sans-serif}button,input{font:inherit}button{padding:9px 13px;border:1px solid #777;background:transparent;color:inherit;cursor:pointer}a{color:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--red);outline-offset:4px}nav{display:flex;flex-wrap:wrap;gap:10px;background:var(--paper);padding:14px 24px;border-bottom:1px solid #aaa}nav a{padding:9px;text-decoration:none}nav a[aria-current]{background:var(--ink);color:var(--paper)}.status{padding:10px 24px;font-size:13px}main{max-width:1440px;margin:auto}.page{background:var(--paper);padding:48px 64px 32px;min-height:900px;display:flex;flex-direction:column}.page[hidden]{display:none}body.overview .page[hidden]{display:flex}body.overview .page{margin-bottom:24px}h1,h2,h3,p{margin-top:0}h1,h2{font-family:"Noto Serif CJK SC","Source Han Serif SC","Songti SC","STSong","SimSun",serif;font-weight:700}h1{font-size:88px;line-height:1.18;letter-spacing:-.035em;margin-bottom:0}h2{font-size:52px;line-height:1.25;letter-spacing:-.035em;margin-bottom:36px}h3{font-size:26px;line-height:1.46;margin-bottom:10px}p{font-size:22px;line-height:1.6;margin-bottom:24px}.meta,footer{font-size:18px;line-height:1.55}footer{display:flex;gap:24px;justify-content:space-between;padding-top:32px;margin-top:auto}.landscape-heading{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:48px;align-items:start;margin:44px 0 54px}.landscape-heading .lead{font-size:26px;line-height:1.54;padding-top:8px;max-width:500px}.photo{margin:0;min-width:0}.image-window{width:100%;position:relative}.image-window img{display:block;width:100%;height:auto}.photo figcaption{font-size:18px;line-height:1.56;margin-top:16px}.photo figcaption strong{display:block;font-weight:400}.object-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.13fr);gap:96px;margin:48px 0 30px;align-items:start}.object-title{grid-column:1;grid-row:1;margin-top:32px}.object-p1{grid-column:1;grid-row:2;margin-top:0}.object-p2{grid-column:1;grid-row:3}.object-grid .photo{grid-column:2;grid-row:1/4}.object-grid p{max-width:540px}.plan h2{font-size:72px;margin-top:40px}.plan .lead{font-size:26px;line-height:1.54;margin-bottom:46px;max-width:1100px}.plan-grid{display:grid;grid-template-columns:minmax(0,2.25fr) minmax(0,1fr);gap:130px}.plan article section+section{margin-top:28px}.plan article p{font-size:22px;line-height:1.6}.plan-aside{padding-top:90px}.plan-aside .pause{font-family:"Noto Serif CJK SC","Songti SC",serif;font-size:46px;line-height:1.3}.plan-aside p{font-size:22px}.time-limit{font-weight:500}.letter-grid{display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:150px;margin:52px 0 30px;align-items:start}.letter-grid .photo{grid-column:1;grid-row:1;padding-top:95px;max-width:440px}.letter-grid article{grid-column:2;grid-row:1}.letter-grid h2{font-size:52px}.letter-grid .ending{margin-top:40px}.source-note{font-size:15px;line-height:1.6}details.editor{max-width:1440px;margin:20px auto;padding:20px 24px;background:white}summary{font-size:19px;cursor:pointer}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0;align-items:center}.tools label{display:flex;gap:8px;align-items:center;flex-wrap:wrap;max-width:100%;min-width:0}.tools input[type=file]{width:240px;max-width:100%;min-width:0}.tool-note{font-size:15px;line-height:1.6}.editing [data-edit]{outline:1px dashed #777;outline-offset:4px}[data-edit]{overflow-wrap:anywhere}.editor-footer{max-width:1440px;margin:0 auto 25px;padding:12px 24px;font-size:13px}body.mono .page{filter:grayscale(1)}@media(max-width:1050px){.page{padding:40px 36px}h1{font-size:66px}.landscape-heading{gap:32px}.object-grid{gap:48px}.plan-grid{gap:60px}.plan h2{font-size:60px}.letter-grid{gap:70px}.letter-grid h2{font-size:46px}.plan-aside .pause{font-size:36px}}@media(max-width:750px){nav{gap:0;padding:8px}nav a{font-size:14px;padding:8px}.status{padding:10px 18px}.page{padding:32px 22px;min-height:800px}h1{font-size:50px}h2{font-size:40px}.meta,footer{font-size:16px}.landscape-heading{display:block;margin:30px 0 35px}.landscape-heading .lead{font-size:23px;padding:0;margin:25px 0 0}.photo figcaption{font-size:16px;line-height:1.65}.object-grid{display:flex;flex-direction:column;gap:0;margin:30px 0}.object-title{margin:0 0 30px;order:0}.object-p1{order:1}.object-grid .photo{order:2;margin:10px 0 30px}.object-p2{order:3}.object-grid p{font-size:22px}.plan h2{font-size:44px;margin-top:30px}.plan .lead{font-size:23px;margin-bottom:32px}.plan-grid{display:block}.plan-aside{padding-top:32px}.plan-aside .pause{font-size:28px}.letter-grid{display:flex;flex-direction:column;gap:30px;margin:30px 0}.letter-grid article{order:0}.letter-grid .photo{order:1;padding:0;width:100%;max-width:420px;align-self:center}.letter-grid h2{font-size:40px}.letter-grid p{font-size:22px}}@media print{body{background:white}nav,.status,.editor,.editor-footer{display:none!important}.page,.page[hidden]{display:flex!important;break-after:page;min-height:0}.photo{break-inside:avoid}.plan article section{break-inside:avoid}}'''
body='<nav aria-label="四页切换">'+''.join(f'<a href="#{k}" data-page="{k}">{i:02} {t}</a>' for i,(k,t) in enumerate([('landscape','场景'),('objects','物件'),('plan','计划'),('letter','短笺')],1))+'</nav><div class="status">温暖插画 · 图画短册候选｜原样例评价：差／二级｜不自动升等</div><main>'
body+='<section class="page" id="landscape"><p class="meta">岸线图画短册／计划草案</p><div class="landscape-heading"><h1>'+e('title','重新看见岸线')+'</h1>'+e('lead','从一幅设想开始，把计划与记录分清楚。','p','lead')+'</div>'+photo('A','一处虚构的水边场景，仅用于引入主题。')+foot('01','进入场景')+'</section>'
body+='<section class="page" id="objects"><p class="meta">准备与记录</p><div class="object-grid"><h2 class="object-title">'+e('object-title','空白，也是一种说明')+'</h2>'+e('object-p1','图里的本子尚未填写。它提示的是一种准备的状态，并不代表计划已经到达现场，也不能替代任何一次记录。','p','object-p1')+photo('B','物件为准备状态的视觉比喻，不是设备清单。')+e('object-p2','这份计划已有数量、轮次和时间设定；具体位置、对应关系和时间范围仍然待定。先保留空白，后面的内容才有机会按真实情况补上。','p','object-p2')+'</div>'+foot('02','物件与说明')+'</section>'
body+='<section class="page plan" id="plan"><p class="meta">计划正文</p><h2>'+e('plan-title','计划写到了哪里')+'</h2>'+e('plan-lead','已有设定可以写清，尚未确定的部分，也应留在明处。','p','lead')+'<div class="plan-grid"><article>'
sections=[('12个观察点','计划给出了观察点的数量，还没有给出它们的名称与位置。插画里的水边、步道或物件，都不能替某一个点位作证。数量已经提出，地点仍待确定。'),('3轮记录','计划给出了轮次，还没有说明点位与轮次怎样对应。这不是已经完成的记录，也不能直接推导出36份记录。安排需要说明，结果需要实际获得。'),('时间设定：30分钟','适用范围待定。目前不能确定它对应单点、单轮还是整个活动，也不能默认平均分为每轮10分钟。明确范围和起止边界之后，才能讨论具体安排。')]
for i,(t,txt) in enumerate(sections,1):body+='<section><h3>'+e(f'section-{i}',t)+'</h3>'+e(f'paragraph-{i}',txt,'p')+'</section>'
body+='</article><aside class="plan-aside">'+e('pause','尚未发生的，先留白。','p','pause')+e('no-result','这里没有实测结果。','p')+'</aside></div>'+foot('03','文字展开')+'</section>'
body+='<section class="page" id="letter"><p class="meta">短册尾声</p><div class="letter-grid"><article><h2>'+e('letter-title','下次，先把这些说清楚')+'</h2>'
for i,t in enumerate(['先为12个观察点补上名称与位置。','再说明3轮记录的安排，以及点位与轮次的对应关系。','最后界定时间设定：30分钟，适用范围待定。说明它用于什么范围，从哪里开始，到哪里结束。','这几件事没有明确之前，让画面停在设想，让记录等待真实发生。'],1):body+=e(f'letter-p{i}',t,'p','ending' if i==4 else '')
body+='</article>'+photo('C','一个独立的叙事停顿，无人物或轮次对应。')+'</div>'+foot('04','人物尾声')+'</section></main><details class="editor"><summary>编辑、图像与导出</summary><div class="tools"><button id="edit" aria-pressed="false">编辑文字</button><button id="overview" aria-pressed="false">四页并看</button><button id="mono" aria-pressed="false">灰度检查</button><button id="reset">恢复初始版本</button></div><div class="tools">'+''.join(f'<label>替换{k} <input id="asset-{k}" type="file" accept="image/png,image/jpeg,image/webp"></label>' for k in ['A','B','C'])+'</div><p class="tool-note">插画保留完整原幅及真实比例。替换只在当前浏览器内处理，请使用有权使用的图片；替换后来源降为用户提供待核，图注需重新审查。画中人物和物件是栅格图像，不宣称可逐项矢量编辑。</p><div class="tools"><button id="json-export">下载含原图 JSON</button><button id="html-export">下载可编辑 HTML</button><label>导入 JSON <input id="json-import" type="file" accept=".json,application/json"></label></div><p id="edit-status" class="tool-note" role="status">默认静态，无动画，暂停不适用。插画不是现场记录。</p><p id="source-note" class="source-note"></p><p class="tool-note">候选局限：A/B仍有轻微色面明暗；C已做一次简化重生，仍保留柔和动画式面部与少量塑形，实际页面仍可辨淡暖白矩形边界。此稿未宣称严格达到纯平色地景语言。</p><p class="tool-note">三张图独立创作，无同地、同人、时间先后或轮次对应。文字修改后需人工核对图意与事实限定。</p></details><div class="editor-footer">WI-NARRATIVE-01 · 原创叙事插画适配；不复制历史原图、人物或刊名字标。系统字体未分发。</div>'
assets=json.loads((p/'asset-config.json').read_text()) if (p/'asset-config.json').exists() else {k:{'src':f'assets/{k.lower()}.png','width':1536 if k=='A' else 1024,'height':512 if k=='A' else 1024,'sourceKind':'pending','name':k+'待接入'} for k in ['A','B','C']}
model={'schemaVersion':1,'designVersion':'WI-NARRATIVE-01','qualityTag':'差','adaptationLevel':2,'candidate':True,'text':{},'assets':assets}
(p/'index.html').write_text('<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>重新看见岸线 · 叙事插画候选</title><style>'+css+'</style></head><body>'+body+'<script id="model" type="application/json">'+json.dumps(model,ensure_ascii=False)+'</script><script>'+(p/'app.js').read_text()+'</script></body></html>')
